import{D as a}from"./chunks/donate.3a95be8c.js";import{o as t,c as o,O as l,X as e}from"./chunks/framework.7fab6bae.js";import"./chunks/wcpay.d0e1a780.js";const r=e('<h1 id="紫微斗数安星诀" tabindex="-1">Zi Wei Dou Shu: Star placement rules（紫微斗數安星訣） <a class="header-anchor" href="#紫微斗数安星诀" aria-label="Permalink to &quot;Zi Wei Dou Shu: Star placement rules（紫微斗數安星訣）   {#紫微斗数安星诀}&quot;">​</a></h1><h2 id="前言" tabindex="-1">Introduction <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;Introduction   {#前言}&quot;">​</a></h2><p>Star-placement rules（安星訣） are the algorithms used to calculate the data for Zi Wei Dou Shu（紫微斗數）. Classical texts present them as easy-to-remember verses. For now, I am recording those verses; detailed explanations will follow. Maintaining this site alone in my spare time takes considerable effort. Please consider <a href="/en_US/about.html">supporting the site</a>.</p><div class="tip custom-block"><p class="custom-block-title">Tips</p><p>This chapter assumes some basic knowledge. If you are new to the subject, I strongly recommend reading <a href="./basis.html">the fundamentals</a> first.</p></div>',4),i=e('<h2 id="安星诀" tabindex="-1">Star placement rules（安星訣） <a class="header-anchor" href="#安星诀" aria-label="Permalink to &quot;Star placement rules（安星訣）   {#安星诀}&quot;">​</a></h2><h3 id="_1-定寅首诀" tabindex="-1">1. Rules for determining the stem of the Yin palace（定寅首訣） <a class="header-anchor" href="#_1-定寅首诀" aria-label="Permalink to &quot;1. Rules for determining the stem of the Yin palace（定寅首訣）   {#_1-定寅首诀}&quot;">​</a></h3><blockquote><p>甲己年生起丙寅，</p><p>乙庚年生起戊寅，</p><p>丙辛年生起庚寅，</p><p>丁壬年生起壬寅，</p><p>戊癸年生起甲寅。</p></blockquote><h3 id="_2-安命身宫诀" tabindex="-1">2. Rules for placing the soul and body palaces（安命身宮訣） <a class="header-anchor" href="#_2-安命身宫诀" aria-label="Permalink to &quot;2. Rules for placing the soul and body palaces（安命身宮訣）   {#_2-安命身宫诀}&quot;">​</a></h3><blockquote><p>寅起正月，順數至生月，逆數生時為命宮。</p><p>寅起正月，順數至生月，順數生時為身宮。</p></blockquote><h3 id="_3-定十二宫诀" tabindex="-1">3. Rules for placing the twelve palaces（定十二宮訣） <a class="header-anchor" href="#_3-定十二宫诀" aria-label="Permalink to &quot;3. Rules for placing the twelve palaces（定十二宮訣）   {#_3-定十二宫诀}&quot;">​</a></h3><blockquote><p>由命宮逆數：兄弟、夫妻、子女、財帛、疾厄、遷移、奴僕、事業、田宅、福德、父母。</p></blockquote><h3 id="_4-起大限诀" tabindex="-1">4. Rules for determining decadal periods（起大限訣） <a class="header-anchor" href="#_4-起大限诀" aria-label="Permalink to &quot;4. Rules for determining decadal periods（起大限訣）   {#_4-起大限诀}&quot;">​</a></h3><blockquote><p>大限由命宮起，</p><p>陽男陰女順行；</p><p>陰男陽女逆行，</p><p>每十年過一宮限。</p></blockquote><h3 id="_5-起小限诀" tabindex="-1">5. Rules for determining annual age periods（起小限訣） <a class="header-anchor" href="#_5-起小限诀" aria-label="Permalink to &quot;5. Rules for determining annual age periods（起小限訣）   {#_5-起小限诀}&quot;">​</a></h3><blockquote><p>小限一年一度逢，男順女逆不相同，</p><p>寅午戌人辰上起，申子辰人自戌宮，</p><p>巳酉丑人未宮始，亥卯未人起丑宮。</p></blockquote><h3 id="_6-安命主诀" tabindex="-1">6. Rules for determining the soul ruler（安命主訣） <a class="header-anchor" href="#_6-安命主诀" aria-label="Permalink to &quot;6. Rules for determining the soul ruler（安命主訣）   {#_6-安命主诀}&quot;">​</a></h3><blockquote><p>子屬貪狼丑亥門，</p><p>寅戌生人屬祿存。</p><p>卯酉屬文巳未武，</p><p>辰申廉宿午破軍。</p></blockquote><div class="tip custom-block"><p class="custom-block-title">Tips</p><p>By default, the library determines the soul ruler（命主） from the earthly branch of the soul palace（命宮）. With the Zhongzhou（中州派） algorithm, it uses the birth year’s earthly branch instead.</p></div><h3 id="_7-安身主诀" tabindex="-1">7. Rules for determining the body ruler（安身主訣） <a class="header-anchor" href="#_7-安身主诀" aria-label="Permalink to &quot;7. Rules for determining the body ruler（安身主訣）   {#_7-安身主诀}&quot;">​</a></h3><blockquote><p>子午安身鈴火宿，</p><p>丑未天相寅申梁，</p><p>卯酉天同身主是，</p><p>巳亥天機辰戌昌。</p></blockquote><div class="tip custom-block"><p class="custom-block-title">Tips</p><p>The body ruler（身主） is determined from the birth year’s earthly branch. Versions of this mnemonic may differ; the library uses impulsive（火星） as the body ruler for both Zi（子） and Woo（午） years.</p></div><h3 id="_8-起紫微星诀" tabindex="-1">8. Rules for placing emperor（起紫微星訣） <a class="header-anchor" href="#_8-起紫微星诀" aria-label="Permalink to &quot;8. Rules for placing emperor（起紫微星訣）   {#_8-起紫微星诀}&quot;">​</a></h3><blockquote><p>六五四三二，酉午亥辰丑，</p><p>局數除日數，商數宮前走；</p><p>若見數無餘，便要起虎口，</p><p>日數小於局，還直宮中守。</p></blockquote><h3 id="_9-安天府星诀" tabindex="-1">9. Rules for placing empress（安天府星訣） <a class="header-anchor" href="#_9-安天府星诀" aria-label="Permalink to &quot;9. Rules for placing empress（安天府星訣）   {#_9-安天府星诀}&quot;">​</a></h3><blockquote><p>天府南斗令，常對紫微宮，</p><p>丑卯相更迭，未酉互為根。</p><p>往來午與戌，蹀躞子和辰，</p><p>巳亥交馳騁，同位在寅申。</p></blockquote><div class="tip custom-block"><p class="custom-block-title">Tips</p><p>Determine the position from emperor（紫微）.</p></div><h3 id="_10-安紫微诸星诀" tabindex="-1">10. Rules for placing emperor star group（安紫微諸星訣） <a class="header-anchor" href="#_10-安紫微诸星诀" aria-label="Permalink to &quot;10. Rules for placing emperor star group（安紫微諸星訣）   {#_10-安紫微诸星诀}&quot;">​</a></h3><blockquote><p>紫微逆去天機星，</p><p>隔一太陽武曲辰，</p><p>連接天同空二宮，</p><p>廉貞居處方是真。</p></blockquote><h3 id="_11-安天府诸星诀" tabindex="-1">11. Rules for placing empress star group（安天府諸星訣） <a class="header-anchor" href="#_11-安天府诸星诀" aria-label="Permalink to &quot;11. Rules for placing empress star group（安天府諸星訣）   {#_11-安天府诸星诀}&quot;">​</a></h3><blockquote><p>天府順行有太陰，</p><p>貪狼而後巨門臨，</p><p>隨來天相天梁繼，</p><p>七殺空三是破軍。</p></blockquote><h3 id="_12-定五行局诀" tabindex="-1">12. Rules for determining the Five Elements Class（定五行局訣） <a class="header-anchor" href="#_12-定五行局诀" aria-label="Permalink to &quot;12. Rules for determining the Five Elements Class（定五行局訣）   {#_12-定五行局诀}&quot;">​</a></h3><blockquote><p>甲乙丙丁一到五，子丑午未一來數，</p><p>寅卯申酉二上走，辰巳戌亥三為足。</p><p>干支相加多減五，五行木金水火土。</p></blockquote><p>Note:</p><ol><li><p>Five-element values（五行取數）: wood 1, metal 2, water 3, fire 4, earth 5.</p><ul><li><p>Heavenly-stem values（天干取數）:</p><ul><li>Jia, Yi（甲乙） → 1</li><li>Bing, Ding（丙丁） → 2</li><li>Wu, Ji（戊己） → 3</li><li>Geng, Xin（庚辛） → 4</li><li>Ren, Gui（壬癸） → 5</li></ul></li><li><p>Earthly-branch values（地支取數）:</p><ul><li>Zi, Wu, Chou, Wei（子午丑未） → 1</li><li>Yin, Shen, Mao, You（寅申卯酉） → 2</li><li>Chen, Xu, Si, Hai（辰戌巳亥） → 3</li></ul></li></ul></li><li><p>Calculation method:</p><p>Add the heavenly-stem and earthly-branch values. If the sum exceeds 5, subtract 5. The resulting values 1, 2, 3, 4, and 5 correspond to wood, metal, water, fire, and earth.</p></li><li><p>Example:</p><ul><li>bing（丙） + zi（子）: 2+1=3 → Water（水） → water 2nd（水二局）</li><li>Xin-Wei（辛未）: 4+1=5 → earth（土） → earth 5th（土五局）.</li><li>geng（庚） + shen（申）: 4+2=6 → 6−5=1 → Wood（木） → wood 3rd（木三局）</li></ul></li></ol><h3 id="_13-安辅弼、昌曲、空劫诀" tabindex="-1">13. Rules for placing officer, helper, scholar, artist, ideologue, fickle（安輔弼、昌曲、空劫訣） <a class="header-anchor" href="#_13-安辅弼、昌曲、空劫诀" aria-label="Permalink to &quot;13. Rules for placing officer, helper, scholar, artist, ideologue, fickle（安輔弼、昌曲、空劫訣）   {#_13-安辅弼、昌曲、空劫诀}&quot;">​</a></h3><blockquote><p>辰上順正尋左輔，戌上逆正右弼當，</p><p>辰上順時文曲位，戌上逆時覓文昌，</p><p>亥上子時順安劫，逆回便是地空亡。</p></blockquote><h3 id="_14-安魁钺诀" tabindex="-1">14. Rules for placing assistant, aide（安魁鉞訣） <a class="header-anchor" href="#_14-安魁钺诀" aria-label="Permalink to &quot;14. Rules for placing assistant, aide（安魁鉞訣）   {#_14-安魁钺诀}&quot;">​</a></h3><blockquote><p>甲戊庚之年丑未，</p><p>乙己之年子申，</p><p>辛年午寅，</p><p>壬癸之年卯巳，</p><p>丙丁之年亥酉。</p></blockquote><h3 id="_15-定禄存、羊、陀诀" tabindex="-1">15. Rules for placing money, driven, tangled（定祿存、羊、陀訣） <a class="header-anchor" href="#_15-定禄存、羊、陀诀" aria-label="Permalink to &quot;15. Rules for placing money, driven, tangled（定祿存、羊、陀訣）   {#_15-定禄存、羊、陀诀}&quot;">​</a></h3><blockquote><p>甲祿到寅宮，乙祿居卯府。</p><p>丙戊祿在巳，丁己祿在午。</p><p>庚祿定居申，辛祿酉上補。</p><p>壬祿亥中藏，癸祿居子戶。</p><p>祿前羊刃當，祿後陀羅府。</p></blockquote><h3 id="_16-安天马诀" tabindex="-1">16. Rules for placing horse（安天馬訣） <a class="header-anchor" href="#_16-安天马诀" aria-label="Permalink to &quot;16. Rules for placing horse（安天馬訣）   {#_16-安天马诀}&quot;">​</a></h3><blockquote><p>寅午戌年馬在申，申子辰年馬在寅。</p><p>巳酉丑年馬在亥，亥卯未年馬在巳。</p></blockquote><div class="tip custom-block"><p class="custom-block-title">Tips</p><p>Use the earthly branch（地支） of the birth year.</p></div><h3 id="_17-安火铃诀" tabindex="-1">17. Rules for placing impulsive, spark（安火鈴訣） <a class="header-anchor" href="#_17-安火铃诀" aria-label="Permalink to &quot;17. Rules for placing impulsive, spark（安火鈴訣）   {#_17-安火铃诀}&quot;">​</a></h3><blockquote><p>申子辰人寅戌揚，寅午戌人丑卯方。</p><p>巳酉丑人卯戌位，亥卯未人酉戌房。</p></blockquote><div class="tip custom-block"><p class="custom-block-title">Tips</p><p>To place impulsive（火星） and spark（鈴星）, first use the birth-year branch to find their Zi-hour（子時） starting palaces from the verse.</p></div><p>For a person born in Ren-Chen（壬辰） year at Mao hour（卯時）, <code>申子辰人寅戌揚</code> gives Yin（寅） as impulsive’s（火星） Zi-hour（子時） starting palace and Xu（戌） as spark’s（鈴星）. Count forward to Mao hour: impulsive lands in Si（巳）, and spark in Chou（丑）.</p><h3 id="_18-安四化星诀" tabindex="-1">18. Rules for placing four transformation stars（安四化星訣） <a class="header-anchor" href="#_18-安四化星诀" aria-label="Permalink to &quot;18. Rules for placing four transformation stars（安四化星訣）   {#_18-安四化星诀}&quot;">​</a></h3><blockquote><p>甲廉破武陽，乙機梁紫陰，</p><p>丙同機昌廉，丁陰同機巨，</p><p>戊貪陰右機。己武貪梁曲，</p><p>庚陽武陰同，辛巨陽曲昌，</p><p>壬梁紫左武，癸破巨陰貪。</p></blockquote><div class="tip custom-block"><p class="custom-block-title">Tips</p><p>Transformation assignments（四化） vary by school; the list above follows the Southern School.</p></div><h3 id="_19-安台辅封诰诀" tabindex="-1">19. Rules for placing honorable, awarded（安台輔封誥訣） <a class="header-anchor" href="#_19-安台辅封诰诀" aria-label="Permalink to &quot;19. Rules for placing honorable, awarded（安台輔封誥訣）   {#_19-安台辅封诰诀}&quot;">​</a></h3><blockquote><p>臺輔午起子順到時，封誥寅宮起子逆到時。</p></blockquote><h3 id="_20-安天刑天姚诀" tabindex="-1">20. Rules for placing serious, social（安天刑天姚訣） <a class="header-anchor" href="#_20-安天刑天姚诀" aria-label="Permalink to &quot;20. Rules for placing serious, social（安天刑天姚訣）   {#_20-安天刑天姚诀}&quot;">​</a></h3><blockquote><p>天刑從酉起正月，順至生月便安之。</p><p>天姚丑宮起正月，順到生月即停留。</p></blockquote><h3 id="_21-安解神诀" tabindex="-1">21. Rules for placing considery（安解神訣） <a class="header-anchor" href="#_21-安解神诀" aria-label="Permalink to &quot;21. Rules for placing considery（安解神訣）   {#_21-安解神诀}&quot;">​</a></h3><ul><li><p>Monthly considery（月解）</p><p>Monthly considery（月解） is placed according to the birth month.</p><blockquote><p>正二在申三四在戌，</p><p>五六在子七八在寅。</p><p>九十月坐於辰宮，</p><p>十一十二在午宮。</p></blockquote></li><li><p>Yearly considery（年解）</p><p>Yearly considery（年解） is the annual form of considery（解神）. It belongs to <code>transit stars</code>（流曜） and changes position each year.</p><blockquote><p>解神從戌上起子，逆數至當生年太歲上是也</p></blockquote></li></ul><h3 id="_22-安天巫诀" tabindex="-1">22. Rules for placing psychic（安天巫訣） <a class="header-anchor" href="#_22-安天巫诀" aria-label="Permalink to &quot;22. Rules for placing psychic（安天巫訣）   {#_22-安天巫诀}&quot;">​</a></h3><blockquote><p>正五九月在巳，二六十月在申，</p><p>三七十一在寅，四八十二在亥。</p></blockquote><h3 id="_23-安天月诀" tabindex="-1">23. Rules for placing sickly（安天月訣） <a class="header-anchor" href="#_23-安天月诀" aria-label="Permalink to &quot;23. Rules for placing sickly（安天月訣）   {#_23-安天月诀}&quot;">​</a></h3><blockquote><p>一犬二蛇三在龍，四虎五羊六兔宮。</p><p>七豬八羊九在虎，十馬冬犬臘寅中。</p></blockquote><h3 id="_24-安阴煞诀" tabindex="-1">24. Rules for placing gloomy（安陰煞訣） <a class="header-anchor" href="#_24-安阴煞诀" aria-label="Permalink to &quot;24. Rules for placing gloomy（安陰煞訣）   {#_24-安阴煞诀}&quot;">​</a></h3><blockquote><p>正七月在寅，二八月在子，</p><p>三九月在戌，四十月在申，</p><p>五十一在午，六十二在辰。</p></blockquote><h3 id="_25-安截路空亡诀" tabindex="-1">25. Rules for placing interrupted（安截路空亡訣） <a class="header-anchor" href="#_25-安截路空亡诀" aria-label="Permalink to &quot;25. Rules for placing interrupted（安截路空亡訣）   {#_25-安截路空亡诀}&quot;">​</a></h3><blockquote><p>甲己之年申酉，</p><p>乙庚之年午未，</p><p>丙辛之年辰巳，</p><p>丁壬之年寅卯，</p><p>戊癸之年子丑。</p></blockquote><h3 id="_26-安天官天福贵人诀" tabindex="-1">26. Rules for placing solemn, lucky（安天官天福貴人訣） <a class="header-anchor" href="#_26-安天官天福贵人诀" aria-label="Permalink to &quot;26. Rules for placing solemn, lucky（安天官天福貴人訣）   {#_26-安天官天福贵人诀}&quot;">​</a></h3><blockquote><p>甲喜羊雞乙龍猴，丙年蛇鼠一窩謀。</p><p>丁虎擒豬戊玉兔，己雞居然與虎儔。</p><p>庚豬馬辛雞蛇走，壬犬馬癸馬蛇遊。</p></blockquote><h3 id="_27-安天空诀" tabindex="-1">27. Rules for placing utopian（安天空訣） <a class="header-anchor" href="#_27-安天空诀" aria-label="Permalink to &quot;27. Rules for placing utopian（安天空訣）   {#_27-安天空诀}&quot;">​</a></h3><blockquote><p>生年支順數的前一位就是。</p></blockquote><h3 id="_28-安天哭天虚诀" tabindex="-1">28. Rules for placing upset, frail（安天哭天虛訣） <a class="header-anchor" href="#_28-安天哭天虚诀" aria-label="Permalink to &quot;28. Rules for placing upset, frail（安天哭天虛訣）   {#_28-安天哭天虚诀}&quot;">​</a></h3><blockquote><p>天哭天虛起午宮，午宮起子兩分蹤，</p><p>哭逆行兮虛順轉，數到生年便停留。</p></blockquote><h3 id="_29-安龙池凤阁诀" tabindex="-1">29. Rules for placing talented, refined（安龍池鳳閣訣） <a class="header-anchor" href="#_29-安龙池凤阁诀" aria-label="Permalink to &quot;29. Rules for placing talented, refined（安龍池鳳閣訣）   {#_29-安龙池凤阁诀}&quot;">​</a></h3><blockquote><p>龍池從辰宮起子，</p><p>順至本生年支安之。</p><p>鳳閣從戌宮起子，</p><p>逆行至本生年支安之。</p></blockquote><h3 id="_30-安红鸾天喜诀" tabindex="-1">30. Rules for placing attractive, cheerful（安紅鸞天喜訣） <a class="header-anchor" href="#_30-安红鸾天喜诀" aria-label="Permalink to &quot;30. Rules for placing attractive, cheerful（安紅鸞天喜訣）   {#_30-安红鸾天喜诀}&quot;">​</a></h3><blockquote><p>卯上起子逆數之，數到當生太歲支。</p><p>坐守此宮紅鸞位，對宮天喜不差移。</p></blockquote><h3 id="_31-安孤辰寡宿诀" tabindex="-1">31. Rules for placing alone, lonely（安孤辰寡宿訣） <a class="header-anchor" href="#_31-安孤辰寡宿诀" aria-label="Permalink to &quot;31. Rules for placing alone, lonely（安孤辰寡宿訣）   {#_31-安孤辰寡宿诀}&quot;">​</a></h3><blockquote><p>寅卯辰年安巳丑，巳午未年安申辰，</p><p>申酉戌年安亥未，亥子丑年安寅戌。</p></blockquote><h3 id="_32-安蜚廉诀" tabindex="-1">32. Rules for placing instigated（安蜚廉訣） <a class="header-anchor" href="#_32-安蜚廉诀" aria-label="Permalink to &quot;32. Rules for placing instigated（安蜚廉訣）   {#_32-安蜚廉诀}&quot;">​</a></h3><blockquote><p>子丑寅年在申酉戌，卯辰巳年在巳午未，</p><p>午未申年在寅卯辰，酉戌亥年在亥子丑。</p></blockquote><h3 id="_33-安破碎诀" tabindex="-1">33. Rules for placing broken（安破碎訣） <a class="header-anchor" href="#_33-安破碎诀" aria-label="Permalink to &quot;33. Rules for placing broken（安破碎訣）   {#_33-安破碎诀}&quot;">​</a></h3><blockquote><p>子午卯酉年安巳宮，</p><p>寅申巳亥年安酉宮，</p><p>辰戌丑未年安丑宮。</p></blockquote><h3 id="_34-安华盖诀" tabindex="-1">34. Rules for placing religious（安華蓋訣） <a class="header-anchor" href="#_34-安华盖诀" aria-label="Permalink to &quot;34. Rules for placing religious（安華蓋訣）   {#_34-安华盖诀}&quot;">​</a></h3><blockquote><p>子辰申年在辰，丑巳酉年在丑，</p><p>寅午戌年在戌，卯未亥年在未。</p></blockquote><h3 id="_35-安咸池诀" tabindex="-1">35. Rules for placing passionate（安咸池訣） <a class="header-anchor" href="#_35-安咸池诀" aria-label="Permalink to &quot;35. Rules for placing passionate（安咸池訣）   {#_35-安咸池诀}&quot;">​</a></h3><blockquote><p>子辰申年在酉，丑巳酉年在午，</p><p>寅午戌年在卯，卯未亥年在子。</p></blockquote><h3 id="_36-安天才天寿诀" tabindex="-1">36. Rules for placing gifted, ageless（安天才天壽訣） <a class="header-anchor" href="#_36-安天才天寿诀" aria-label="Permalink to &quot;36. Rules for placing gifted, ageless（安天才天壽訣）   {#_36-安天才天寿诀}&quot;">​</a></h3><blockquote><p>天才由命宮起子，順行至本生年支安之。</p><p>天壽由身宮起子，順行至本生年支安之。</p></blockquote><h3 id="_37-安三台八座诀" tabindex="-1">37. Rules for placing senior, dignified（安三台八座訣） <a class="header-anchor" href="#_37-安三台八座诀" aria-label="Permalink to &quot;37. Rules for placing senior, dignified（安三台八座訣）   {#_37-安三台八座诀}&quot;">​</a></h3><blockquote><p>由左輔之宮位起初一，順行至生日安三臺。</p><p>由右弼之宮位起初一，逆行至生日安八座。</p></blockquote><h3 id="_38-安恩光天贵诀" tabindex="-1">38. Rules for placing grateful, noble（安恩光天貴訣） <a class="header-anchor" href="#_38-安恩光天贵诀" aria-label="Permalink to &quot;38. Rules for placing grateful, noble（安恩光天貴訣）   {#_38-安恩光天贵诀}&quot;">​</a></h3><blockquote><p>由文昌之宮位起初一，</p><p>順行至生日再退一步起恩光。</p><p>由文曲之宮位起初一，</p><p>順行至生日再退一步起天貴。</p></blockquote><h3 id="_39-安天厨诀" tabindex="-1">39. Rules for placing gourmet（安天廚訣） <a class="header-anchor" href="#_39-安天厨诀" aria-label="Permalink to &quot;39. Rules for placing gourmet（安天廚訣）   {#_39-安天厨诀}&quot;">​</a></h3><blockquote><p>甲丁食蛇口，乙戊辛馬方。</p><p>丙從鼠口得，己食於猴房。</p><p>庚食虎頭上，壬雞癸豬堂。</p></blockquote><h3 id="_40-安天伤天使诀" tabindex="-1">40. Rules for placing wounded, heaven（安天傷天使訣） <a class="header-anchor" href="#_40-安天伤天使诀" aria-label="Permalink to &quot;40. Rules for placing wounded, heaven（安天傷天使訣）   {#_40-安天伤天使诀}&quot;">​</a></h3><blockquote><p>天傷在僕役宮，天使在疾厄宮。</p></blockquote><h3 id="_41-安长生十二神" tabindex="-1">41. Rules for placing the twelve growth-stage stars（安長生十二神） <a class="header-anchor" href="#_41-安长生十二神" aria-label="Permalink to &quot;41. Rules for placing the twelve growth-stage stars（安長生十二神）   {#_41-安长生十二神}&quot;">​</a></h3><blockquote><p>水二局長生在申，</p><p>木三局長生在亥，</p><p>金四局長生在巳，</p><p>土五局長生在申，</p><p>火六局長生在寅 ，</p><p>陽男陰女順行，</p><p>陰男陽女逆行.</p><p>安長生、沐浴、冠帶、臨官、帝旺、衰、病、死、墓、絕 、胎、養。</p></blockquote><h3 id="_42-安博士十二神" tabindex="-1">42. Rules for placing the twelve Doctor-cycle stars（安博士十二神） <a class="header-anchor" href="#_42-安博士十二神" aria-label="Permalink to &quot;42. Rules for placing the twelve Doctor-cycle stars（安博士十二神）   {#_42-安博士十二神}&quot;">​</a></h3><blockquote><p>從祿存起，</p><p>陽男陰女順行，</p><p>陰男陽女逆行。</p><p>安博士、力士、青龍、小耗、將軍、奏書、飛廉、喜神、病符、大耗、伏兵、官府。</p></blockquote><h3 id="_43-安流年岁前十二神" tabindex="-1">43. Rules for placing the twelve yearly Year-front stars（安流年歲前十二神） <a class="header-anchor" href="#_43-安流年岁前十二神" aria-label="Permalink to &quot;43. Rules for placing the twelve yearly Year-front stars（安流年歲前十二神）   {#_43-安流年岁前十二神}&quot;">​</a></h3><blockquote><p>流年地支起歲建，歲前首先是晦氣，</p><p>喪門貫索及官符，小耗大耗龍德繼，</p><p>白虎天德連吊客，病符居後須當記。</p></blockquote><h3 id="_44-安流年将前十二神" tabindex="-1">44. Rules for placing the twelve yearly General-front stars（安流年將前十二神） <a class="header-anchor" href="#_44-安流年将前十二神" aria-label="Permalink to &quot;44. Rules for placing the twelve yearly General-front stars（安流年將前十二神）   {#_44-安流年将前十二神}&quot;">​</a></h3><blockquote><p>寅午戌年將星午，申子辰年子將星，</p><p>巳酉丑將酉上駐，亥卯未將卯上停。</p><p>攀鞍歲驛並息神，華蓋劫煞災煞輕，</p><p>天煞指背咸池續，月煞亡神次第行。</p></blockquote><div class="tip custom-block"><p class="custom-block-title">Tips</p><p>Place <code>capable</code>（將星） using the annual earthly branch.</p></div><h3 id="_45-安子斗诀" tabindex="-1">45. Rules for determining the Zi Dipper direction（安子斗訣） <a class="header-anchor" href="#_45-安子斗诀" aria-label="Permalink to &quot;45. Rules for determining the Zi Dipper direction（安子斗訣）   {#_45-安子斗诀}&quot;">​</a></h3><p>The <code>first-month origin palace</code>（斗君）, also known by the Chinese name 子斗, marks the first lunar month in the monthly cycle. It is calculated from each person&#39;s birth month and double-hour, so it differs between people and changes each year.</p><blockquote><p>流年歲建起正月，逆逢生月順回程，</p><p>回程順至生時止，便是流年正月春。</p></blockquote><div class="tip custom-block"><p class="custom-block-title">Tips</p><p>Use the birth <code>month</code> and <code>hour</code> to find the first lunar month’s palace, then arrange the monthly cycles <code>clockwise</code>. Monthly transformations vary by school: some use the <code>palace stem</code>（宮干） directly, while others derive a heavenly stem through <code>Five Tigers stem calculation</code>（五虎遁）.</p></div><p>Explanation: start at the palace of the annual earthly branch, taking it as lunar month 1. Count backward to the birth month. In that palace start Zi hour（子時）, then count forward to the birth double-hour; place the first-month origin（斗君） there. Once its birth-year position is known, advance one palace for each subsequent year.</p><h3 id="_46-定流日" tabindex="-1">46. Rules for determining the daily horoscope（定流日） <a class="header-anchor" href="#_46-定流日" aria-label="Permalink to &quot;46. Rules for determining the daily horoscope（定流日）   {#_46-定流日}&quot;">​</a></h3><blockquote><p>以流月所在的宮起初一，</p><p>順行十二宮，一日一宮，</p><p>到月底最後一天止。</p></blockquote><h3 id="_47-定流时" tabindex="-1">47. Rules for determining the hourly horoscope（定流時） <a class="header-anchor" href="#_47-定流时" aria-label="Permalink to &quot;47. Rules for determining the hourly horoscope（定流時）   {#_47-定流时}&quot;">​</a></h3><blockquote><p>在流日所在的宮上起子時，順布十二宮，每一個時辰占一宮。</p></blockquote><h3 id="_48-安流昌流曲诀" tabindex="-1">48. Rules for placing scholar(Y), artist(Y)（安流昌流曲訣） <a class="header-anchor" href="#_48-安流昌流曲诀" aria-label="Permalink to &quot;48. Rules for placing scholar(Y), artist(Y)（安流昌流曲訣）   {#_48-安流昌流曲诀}&quot;">​</a></h3><blockquote><p>流昌起巳位，甲乙順流去，</p><p>不用四墓宮，日月同年歲。</p><p>流曲起酉位，甲乙逆行蹤，</p><p>亦不用四墓，年日月相同。</p></blockquote><div class="warning custom-block"><p class="custom-block-title">Note</p><p>Only the <code>Zhongzhou school</code>（中州派） uses <code>artist(Y)</code>（流曲）; other schools do not.</p></div><h3 id="_49-其余流曜" tabindex="-1">49. Other transit stars（其餘流曜） <a class="header-anchor" href="#_49-其余流曜" aria-label="Permalink to &quot;49. Other transit stars（其餘流曜）   {#_49-其余流曜}&quot;">​</a></h3><blockquote><p>魁鉞祿羊陀四化加流馬和天盤一樣；</p><p>運馬是以大限地支。</p><p>流馬是以流年地支。</p></blockquote><div class="warning custom-block"><p class="custom-block-title">Note</p><p>Transit stars（流曜） are generally considered primarily for <code>decadal</code>（大限） and <code>yearly</code>（流年） cycles, with monthly, daily, and hourly transit stars used less often in traditional readings. Since v2.4.4, this library also provides transit stars for those three levels. To distinguish their names, <code>decadal</code>（大限） stars use a <code>decadal marker</code>, and <code>yearly</code>（流年） stars an <code>annual marker</code>. For example, decadal <code>horse</code>（天馬） is called <code>horse(D)</code>（運馬）, while <code>yearly</code>（流年） <code>horse</code>（天馬） is called <code>horse(Y)</code>（流馬）.</p></div>',114),m=JSON.parse('{"title":"Zi Wei Dou Shu star placement rules","description":"Learn the star placement rules used to calculate a Zi Wei Dou Shu chart, from palace positions to stars and time cycles.","frontmatter":{"title":"Zi Wei Dou Shu star placement rules","outline":"deep","description":"Learn the star placement rules used to calculate a Zi Wei Dou Shu chart, from palace positions to stars and time cycles.","head":[["link",{"rel":"canonical","href":"https://iztro.com/en_US/learn/setup.html"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://iztro.com/learn/setup.html"}],["link",{"rel":"alternate","hreflang":"zh-TW","href":"https://iztro.com/zh_TW/learn/setup.html"}],["link",{"rel":"alternate","hreflang":"en-US","href":"https://iztro.com/en_US/learn/setup.html"}],["link",{"rel":"alternate","hreflang":"ko-KR","href":"https://iztro.com/ko_KR/learn/setup.html"}],["link",{"rel":"alternate","hreflang":"ja-JP","href":"https://iztro.com/ja_JP/learn/setup.html"}],["link",{"rel":"alternate","hreflang":"vi-VN","href":"https://iztro.com/vi_VN/learn/setup.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://iztro.com/learn/setup.html"}],["meta",{"name":"robots","content":"max-image-preview:large"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"紫微研习社"}],["meta",{"property":"og:title","content":"Zi Wei Dou Shu star placement rules | 紫微研习社"}],["meta",{"property":"og:description","content":"Learn the star placement rules used to calculate a Zi Wei Dou Shu chart, from palace positions to stars and time cycles."}],["meta",{"property":"og:url","content":"https://iztro.com/en_US/learn/setup.html"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"property":"og:locale:alternate","content":"zh_CN"}],["meta",{"property":"og:locale:alternate","content":"zh_TW"}],["meta",{"property":"og:locale:alternate","content":"ko_KR"}],["meta",{"property":"og:locale:alternate","content":"ja_JP"}],["meta",{"property":"og:locale:alternate","content":"vi_VN"}],["meta",{"property":"og:image","content":"https://iztro.com/static/home_img.png"}],["meta",{"property":"og:image:width","content":"850"}],["meta",{"property":"og:image:height","content":"850"}],["meta",{"property":"og:image:alt","content":"紫微研习社"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"Zi Wei Dou Shu star placement rules | 紫微研习社"}],["meta",{"name":"twitter:description","content":"Learn the star placement rules used to calculate a Zi Wei Dou Shu chart, from palace positions to stars and time cycles."}],["meta",{"name":"twitter:image","content":"https://iztro.com/static/home_img.png"}],["meta",{"name":"twitter:image:alt","content":"紫微研习社"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://iztro.com/en_US/learn/setup.html#webpage\\",\\"url\\":\\"https://iztro.com/en_US/learn/setup.html\\",\\"name\\":\\"Zi Wei Dou Shu star placement rules | 紫微研习社\\",\\"description\\":\\"Learn the star placement rules used to calculate a Zi Wei Dou Shu chart, from palace positions to stars and time cycles.\\",\\"inLanguage\\":\\"en-US\\",\\"isPartOf\\":{\\"@id\\":\\"https://iztro.com/#website\\"},\\"breadcrumb\\":{\\"@id\\":\\"https://iztro.com/en_US/learn/setup.html#breadcrumb\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"@id\\":\\"https://iztro.com/en_US/learn/setup.html#breadcrumb\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"紫微研习社\\",\\"item\\":\\"https://iztro.com/en_US/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Zi Wei Dou Shu star placement rules\\",\\"item\\":\\"https://iztro.com/en_US/learn/setup.html\\"}]}]}"]]},"headers":[],"relativePath":"en_US/learn/setup.md","filePath":"en_US/learn/setup.md"}'),s={name:"en_US/learn/setup.md"},b=Object.assign(s,{setup(n){return(p,c)=>(t(),o("div",null,[r,l(a),i]))}});export{m as __pageData,b as default};
